        if matches!(operation,"translate"|"rotate"|"scale") {
            let values=mesh.halfedges.iter().map(|edge|{let normal=mesh.face_normal(FaceId(edge.face.unwrap())).unwrap();protocol::value::DslValue::Array(normal.0.into_iter().map(|x|protocol::value::DslValue::float(x as f64)).collect())}).collect();mesh.set_attribute("normal".into(),MeshAttribute { indices:None,domain:MeshAttributeDomain::Corner,semantic:MeshAttributeSemantic::Normal,interpolation:MeshAttributeInterpolation::Linear,values}).unwrap();
        }
